<?php
session_start();
if(!isset($_SESSION['userName'])||$_SESSION['userName']!=='admin'){header('Location: alogin.php');exit;}
if(isset($_POST['logout'])){session_unset();session_destroy();header('Location: ../cover.php');exit;}
require 'dbconfig.php';
$message='';$messageType='';
$cities=[];$q=$conn->query('SELECT DISTINCT City FROM clinic ORDER BY City');while($r=$q->fetch_assoc())$cities[]=$r['City'];
$dayMap=['Monday'=>'Pazartesi','Tuesday'=>'Salı','Wednesday'=>'Çarşamba','Thursday'=>'Perşembe','Friday'=>'Cuma','Saturday'=>'Cumartesi','Sunday'=>'Pazar'];

if(isset($_POST['Submit'])){
    $did=(int)($_POST['did']??0);$name=trim($_POST['name']??'');$gender=$_POST['gender']??'';$dob=$_POST['dob']??'';
    $experience=filter_input(INPUT_POST,'experience',FILTER_VALIDATE_INT);$specialization=trim($_POST['specialization']??'');$contact=trim($_POST['contact']??'');
    $address=trim($_POST['address']??'');$username=trim($_POST['username']??'');$password=$_POST['pwd']??'';$region=trim($_POST['region']??'');
    $city=trim($_POST['city']??'');$cid=(int)($_POST['clinic']??0);$start=$_POST['starttime']??'';$end=$_POST['endtime']??'';
    $days=$_POST['daylist']??[];$validDays=array_values(array_intersect(array_keys($dayMap),is_array($days)?$days:[]));
    $dateObject=DateTime::createFromFormat('!Y-m-d',$dob);$dateErrors=DateTime::getLastErrors();if($dateErrors===false)$dateErrors=['warning_count'=>0,'error_count'=>0];

    if($did<=0||!$name||!in_array($gender,['female','male'],true)||!$dateObject||$dateErrors['warning_count']||$dateErrors['error_count']||$experience===false||$experience<0||!$specialization||!$contact||!$address||!$username||strlen($password)<6||!$region||$city===''||$cid<=0||!$start||!$end||!$validDays){
        $message='Tüm alanları geçerli şekilde doldurun. Klinik, çalışma günleri ve saatleri zorunludur.';$messageType='error';
    }elseif($start>=$end){$message='Başlangıç saati bitiş saatinden önce olmalıdır.';$messageType='error';}
    else{
        $conn->begin_transaction();
        try{
            $q=$conn->prepare('SELECT DID FROM doctor WHERE DID=? OR Username=? LIMIT 1');$q->bind_param('is',$did,$username);$q->execute();$exists=$q->get_result()->fetch_assoc();$q->close();
            if($exists)throw new RuntimeException('exists');

            $q=$conn->prepare('SELECT CID FROM clinic WHERE CID=? AND City=? LIMIT 1');$q->bind_param('is',$cid,$city);$q->execute();$clinic=$q->get_result()->fetch_assoc();$q->close();
            if(!$clinic)throw new RuntimeException('clinic');

            $hash=password_hash($password,PASSWORD_DEFAULT);
            $q=$conn->prepare('INSERT INTO doctor (DID,Name,Gender,DOB,Experience,Specialization,Contact,Address,Username,Password,Region) VALUES (?,?,?,?,?,?,?,?,?,?,?)');
            $q->bind_param('isssissssss',$did,$name,$gender,$dob,$experience,$specialization,$contact,$address,$username,$hash,$region);$q->execute();$q->close();

            $q=$conn->prepare('INSERT INTO doctor_clinic (CID,DID) VALUES (?,?)');$q->bind_param('ii',$cid,$did);$q->execute();$q->close();
            $q=$conn->prepare('INSERT INTO doctor_availability (CID,DID,Day,Starttime,Endtime) VALUES (?,?,?,?,?)');
            foreach($validDays as $day){$q->bind_param('iisss',$cid,$did,$day,$start,$end);$q->execute();}$q->close();
            $conn->commit();$message='Doktor başarıyla kaydedildi ve seçilen kliniğe çalışma programıyla atandı.';$messageType='success';
        }catch(Throwable $e){$conn->rollback();$message=$e->getMessage()==='exists'?'DID veya kullanıcı adı zaten mevcut.':($e->getMessage()==='clinic'?'Seçilen klinik belirtilen şehirde bulunamadı.':'Doktor kaydedilirken hata oluştu.');$messageType='error';}
    }
}
?><!doctype html><html lang="tr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Doktor Ekle | Admin</title><link rel="stylesheet" href="adminmain.css"><style>.admin-wrap{width:min(1000px,calc(100% - 32px));margin:30px auto 60px}.page-head{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:22px}.page-head h1{margin:5px 0 7px;font-size:32px}.page-head p{margin:0;color:var(--muted)}.form-card{padding:24px}.section-title{grid-column:1/-1;margin:8px 0 -4px;padding-top:8px;border-top:1px solid var(--border);font-size:15px;font-weight:800;color:var(--text)}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.field-full{grid-column:1/-1}.days{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-top:7px}.day{display:flex;align-items:center;gap:8px;padding:10px;border:1px solid var(--border);border-radius:9px;font-size:13px;font-weight:700}.day input{width:auto}.form-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:22px}.form-actions .button{width:auto}.hint{display:block;margin-top:6px;color:var(--muted);font-size:12px}@media(max-width:700px){.admin-wrap{width:calc(100% - 20px);margin-top:18px}.page-head{align-items:flex-start;flex-direction:column}.page-head .button{width:100%}.form-grid{grid-template-columns:1fr}.section-title,.field-full{grid-column:auto}.days{grid-template-columns:1fr 1fr}.form-actions{display:grid;grid-template-columns:1fr}.form-actions .button{width:100%}}</style></head><body class="admin-page"><header class="site-header"><div class="header-inner"><a class="brand" href="mainpage.php"><img src="../images/cal.png" alt="Appointment"><span>Appointment</span></a><nav><a href="mainpage.php">Panel</a><a class="active" href="adddoctor.php">Doktor Ekle</a></nav></div></header><main class="admin-wrap"><div class="page-head"><div><span class="eyebrow">DOKTOR YÖNETİMİ</span><h1>Yeni doktor ekle</h1><p>Doktor hesabını oluşturun, şehir ve mevcut kliniğini seçin; çalışma programını aynı anda tanımlayın.</p></div><a class="button secondary" href="mainpage.php">Panele Dön</a></div><section class="card form-card"><?php if($message):?><div class="alert <?php echo $messageType;?>"><?php echo htmlspecialchars($message,ENT_QUOTES,'UTF-8');?></div><?php endif;?><form method="post"><div class="form-grid"><div class="field"><label>DID</label><input type="number" name="did" min="1" required></div><div class="field"><label>Ad Soyad</label><input type="text" name="name" maxlength="100" required></div><div class="field"><label>Cinsiyet</label><select name="gender" required><option value="">Seçin</option><option value="female">Kadın</option><option value="male">Erkek</option></select></div><div class="field"><label>Doğum tarihi</label><input type="date" name="dob" required></div><div class="field"><label>Deneyim (yıl)</label><input type="number" min="0" name="experience" required></div><div class="field"><label>Uzmanlık</label><input type="text" name="specialization" required></div><div class="field"><label>Telefon</label><input type="tel" name="contact" required></div><div class="field"><label>Bölge</label><input type="text" name="region" required></div><div class="field field-full"><label>Adres</label><input type="text" name="address" required></div><div class="field"><label>Kullanıcı adı</label><input type="text" name="username" autocomplete="username" required></div><div class="field"><label>Şifre</label><input type="password" name="pwd" autocomplete="new-password" minlength="6" required><small>En az 6 karakter.</small></div><div class="section-title">Klinik ve çalışma programı</div><div class="field"><label>Şehir</label><select name="city" id="city-list" required><option value="">Şehir seçin</option><?php foreach($cities as $c):?><option value="<?php echo htmlspecialchars($c,ENT_QUOTES,'UTF-8');?>"><?php echo htmlspecialchars($c,ENT_QUOTES,'UTF-8');?></option><?php endforeach;?></select></div><div class="field"><label>Klinik</label><select name="clinic" id="clinic-list" required disabled><option value="">Önce şehir seçin</option></select><small class="hint">Yalnızca seçilen şehirdeki mevcut klinikler listelenir.</small></div><div class="field field-full"><label>Çalışma günleri</label><div class="days"><?php foreach($dayMap as $value=>$label):?><label class="day"><input type="checkbox" value="<?php echo $value;?>" name="daylist[]"> <?php echo $label;?></label><?php endforeach;?></div></div><div class="field"><label>Başlangıç</label><input type="time" name="starttime" required></div><div class="field"><label>Bitiş</label><input type="time" name="endtime" required></div></div><div class="form-actions"><a class="button secondary" href="mainpage.php">İptal</a><button class="button" type="submit" name="Submit">Doktoru Kaydet</button></div></form></section></main><script>const city=document.getElementById('city-list'),clinic=document.getElementById('clinic-list');city.addEventListener('change',function(){clinic.disabled=true;clinic.innerHTML='<option value="">Klinikler yükleniyor...</option>';if(!this.value){clinic.innerHTML='<option value="">Önce şehir seçin</option>';return;}fetch('getclinic.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({city:this.value})}).then(r=>{if(!r.ok)throw new Error();return r.text();}).then(html=>{clinic.innerHTML=html;clinic.disabled=false;}).catch(()=>{clinic.innerHTML='<option value="">Klinikler yüklenemedi</option>';});});</script></body></html>